-- FUEL RETAIL WAREHOUSE - INCREMENTAL LOAD
-- Run this AFTER fuel_initial_load.sql against the SAME Azure SQL database.
-- Upsert: updates existing IDs and inserts new IDs; re-runnable safely.
-- Uses newer updated_at timestamps to support ADF incremental / watermark exercises.
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

-- DimCustomer: 70 incoming rows; staging + upsert
SELECT TOP (0) customer_id, customer_name, customer_code, customer_type, city, registration_date, updated_at INTO #DimCustomer FROM dbo.DimCustomer;
-- #DimCustomer: 70 rows

MERGE dbo.DimCustomer WITH (HOLDLOCK) AS target
USING #DimCustomer AS source
ON target.customer_id = source.customer_id
WHEN MATCHED AND source.updated_at > target.updated_at THEN UPDATE SET target.customer_name = source.customer_name, target.customer_code = source.customer_code, target.customer_type = source.customer_type, target.city = source.city, target.registration_date = source.registration_date, target.updated_at = source.updated_at
WHEN NOT MATCHED BY TARGET THEN INSERT (customer_id, customer_name, customer_code, customer_type, city, registration_date, updated_at) VALUES (source.customer_id, source.customer_name, source.customer_code, source.customer_type, source.city, source.registration_date, source.updated_at);
DROP TABLE #DimCustomer;

-- DimStation: 50 incoming rows; staging + upsert
SELECT TOP (0) station_id, station_name, brand, city, state, postal_code, ownership_type, updated_at INTO #DimStation FROM dbo.DimStation;
-- #DimStation: 50 rows

MERGE dbo.DimStation WITH (HOLDLOCK) AS target
USING #DimStation AS source
ON target.station_id = source.station_id
WHEN MATCHED AND source.updated_at > target.updated_at THEN UPDATE SET target.station_name = source.station_name, target.brand = source.brand, target.city = source.city, target.state = source.state, target.postal_code = source.postal_code, target.ownership_type = source.ownership_type, target.updated_at = source.updated_at
WHEN NOT MATCHED BY TARGET THEN INSERT (station_id, station_name, brand, city, state, postal_code, ownership_type, updated_at) VALUES (source.station_id, source.station_name, source.brand, source.city, source.state, source.postal_code, source.ownership_type, source.updated_at);
DROP TABLE #DimStation;

-- DimFuelProduct: 50 incoming rows; staging + upsert
SELECT TOP (0) product_id, product_name, fuel_code, fuel_category, unit_of_measure, list_price, updated_at INTO #DimFuelProduct FROM dbo.DimFuelProduct;
-- #DimFuelProduct: 50 rows

MERGE dbo.DimFuelProduct WITH (HOLDLOCK) AS target
USING #DimFuelProduct AS source
ON target.product_id = source.product_id
WHEN MATCHED AND source.updated_at > target.updated_at THEN UPDATE SET target.product_name = source.product_name, target.fuel_code = source.fuel_code, target.fuel_category = source.fuel_category, target.unit_of_measure = source.unit_of_measure, target.list_price = source.list_price, target.updated_at = source.updated_at
WHEN NOT MATCHED BY TARGET THEN INSERT (product_id, product_name, fuel_code, fuel_category, unit_of_measure, list_price, updated_at) VALUES (source.product_id, source.product_name, source.fuel_code, source.fuel_category, source.unit_of_measure, source.list_price, source.updated_at);
DROP TABLE #DimFuelProduct;

-- DimPump: 30 incoming rows; staging + upsert
SELECT TOP (0) pump_id, station_id, pump_code, pump_status, nozzle_count, updated_at INTO #DimPump FROM dbo.DimPump;
-- #DimPump: 30 rows

MERGE dbo.DimPump WITH (HOLDLOCK) AS target
USING #DimPump AS source
ON target.pump_id = source.pump_id
WHEN MATCHED AND source.updated_at > target.updated_at THEN UPDATE SET target.station_id = source.station_id, target.pump_code = source.pump_code, target.pump_status = source.pump_status, target.nozzle_count = source.nozzle_count, target.updated_at = source.updated_at
WHEN NOT MATCHED BY TARGET THEN INSERT (pump_id, station_id, pump_code, pump_status, nozzle_count, updated_at) VALUES (source.pump_id, source.station_id, source.pump_code, source.pump_status, source.nozzle_count, source.updated_at);
DROP TABLE #DimPump;

-- FactFuelSale: 300 incoming rows; staging + upsert
SELECT TOP (0) sale_id, customer_id, station_id, product_id, pump_id, date_key, quantity_litres, unit_price, gross_amount, discount_amount, net_amount, payment_method, sale_timestamp, updated_at INTO #FactFuelSale FROM dbo.FactFuelSale;
-- #FactFuelSale: 300 rows

MERGE dbo.FactFuelSale WITH (HOLDLOCK) AS target
USING #FactFuelSale AS source
ON target.sale_id = source.sale_id
WHEN MATCHED AND source.updated_at > target.updated_at THEN UPDATE SET target.customer_id = source.customer_id, target.station_id = source.station_id, target.product_id = source.product_id, target.pump_id = source.pump_id, target.date_key = source.date_key, target.quantity_litres = source.quantity_litres, target.unit_price = source.unit_price, target.gross_amount = source.gross_amount, target.discount_amount = source.discount_amount, target.net_amount = source.net_amount, target.payment_method = source.payment_method, target.sale_timestamp = source.sale_timestamp, target.updated_at = source.updated_at
WHEN NOT MATCHED BY TARGET THEN INSERT (sale_id, customer_id, station_id, product_id, pump_id, date_key, quantity_litres, unit_price, gross_amount, discount_amount, net_amount, payment_method, sale_timestamp, updated_at) VALUES (source.sale_id, source.customer_id, source.station_id, source.product_id, source.pump_id, source.date_key, source.quantity_litres, source.unit_price, source.gross_amount, source.discount_amount, source.net_amount, source.payment_method, source.sale_timestamp, source.updated_at);
DROP TABLE #FactFuelSale;

-- FactInventoryReading: 120 incoming rows; staging + upsert
SELECT TOP (0) reading_id, station_id, product_id, date_key, opening_stock_litres, received_litres, sold_litres, closing_stock_litres, reading_timestamp, updated_at INTO #FactInventoryReading FROM dbo.FactInventoryReading;
-- #FactInventoryReading: 120 rows

MERGE dbo.FactInventoryReading WITH (HOLDLOCK) AS target
USING #FactInventoryReading AS source
ON target.reading_id = source.reading_id
WHEN MATCHED AND source.updated_at > target.updated_at THEN UPDATE SET target.station_id = source.station_id, target.product_id = source.product_id, target.date_key = source.date_key, target.opening_stock_litres = source.opening_stock_litres, target.received_litres = source.received_litres, target.sold_litres = source.sold_litres, target.closing_stock_litres = source.closing_stock_litres, target.reading_timestamp = source.reading_timestamp, target.updated_at = source.updated_at
WHEN NOT MATCHED BY TARGET THEN INSERT (reading_id, station_id, product_id, date_key, opening_stock_litres, received_litres, sold_litres, closing_stock_litres, reading_timestamp, updated_at) VALUES (source.reading_id, source.station_id, source.product_id, source.date_key, source.opening_stock_litres, source.received_litres, source.sold_litres, source.closing_stock_litres, source.reading_timestamp, source.updated_at);
DROP TABLE #FactInventoryReading;

COMMIT TRANSACTION;

-- Expected final table counts: Customer 520, Station 510, Product 510, Date 365, Pump 210, Sales 1200, Inventory 480.
SELECT DimCustomer AS table_name,COUNT(*) AS row_count FROM dbo.DimCustomer UNION ALL
SELECT DimStation,COUNT(*) FROM dbo.DimStation UNION ALL
SELECT DimFuelProduct,COUNT(*) FROM dbo.DimFuelProduct UNION ALL
SELECT DimDate,COUNT(*) FROM dbo.DimDate UNION ALL
SELECT DimPump,COUNT(*) FROM dbo.DimPump UNION ALL
SELECT FactFuelSale,COUNT(*) FROM dbo.FactFuelSale UNION ALL
SELECT FactInventoryReading,COUNT(*) FROM dbo.FactInventoryReading;
